function downloadReport(collection){ const link=document.createElement('a');const params=new URLSearchParams();const from=$('#report-from')?.value,to=$('#report-to')?.value,storeId=$('#report-store')?.value;if(from)params.set('from',from);if(to)params.set('to',to);if(storeId)params.set('storeId',storeId);const query=params.toString();const request=api.download(`/api/report-pdf/${encodeURIComponent(collection)}.pdf${query?`?${query}`:''}`,{headers:{Accept:'application/pdf','X-Tenant-ID':activeTenantId()}}).then(async response=>{const type=response.headers.get('content-type')||'';const blob=await response.blob();if(!type.includes('application/pdf')||blob.size<4||String.fromCharCode(...new Uint8Array(await blob.slice(0,4).arrayBuffer()))!=='%PDF')throw new Error('El servidor no devolvio un PDF valido.');return blob;}).then(blob=>{const url=URL.createObjectURL(blob);link.href=url;link.download=`famimuebles-${collection}.pdf`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Reporte PDF descargado correctamente.');}).catch(error=>showToast(error.message,'error')); return request; }
