function openStoreModal(storeId=''){ const storeItem=storeId && store.collection.stores.find(item=>item.id===storeId); modal(storeItem ? 'Editar local' : 'Nuevo local', [{name:'name',label:'Nombre',value:storeItem?.name||''},{name:'code',label:'Codigo',value:storeItem?.code||''},{name:'address',label:'Direccion',value:storeItem?.address||'',required:false},{name:'phone',label:'Telefono',value:storeItem?.phone||'',required:false},{name:'status',label:'Estado',value:storeItem?.status||'Activo'}],async values=>{ const payload={id:storeItem?.id||generateId('LOC',store.collection.stores),name:values.name,code:values.code,address:values.address||'',phone:values.phone||'',status:values.status||'Activo'}; await persistCatalogRecord('/api/catalog/store',payload,storeItem?'PUT':'POST'); const normalized=await hydrateState(); if(normalized){store.state=normalized;await hydrateCatalog(store.state);} $('#modal-root').innerHTML=''; render(); showToast(storeItem ? 'Local actualizado correctamente.' : 'Local guardado correctamente.'); }); }
function showStoreDetail(storeId){ const storeItem=store.collection.stores.find(item=>item.id===storeId); if(!storeItem) return; const inventoryCount=(store.collection.inventoryByStore||[]).filter(item=>String(item.storeId)===String(storeId)).length; const inventoryUnits=(store.collection.inventoryByStore||[]).filter(item=>String(item.storeId)===String(storeId)).reduce((sum,item)=>sum+Number(item.quantity||0),0); $('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><button type="button" class="modal-close">×</button><p class="eyebrow">LOCAL</p><h2>${storeItem.name || storeItem.code || 'Detalle del local'}</h2><div class="detail-grid"><div><span class="muted">Codigo</span><strong>${storeItem.code || '-'}</strong></div><div><span class="muted">Estado</span><strong>${storeItem.status || 'Activo'}</strong></div><div><span class="muted">Direccion</span><strong>${storeItem.address || 'Sin direccion'}</strong></div><div><span class="muted">Telefono</span><strong>${storeItem.phone || 'Sin telefono'}</strong></div><div><span class="muted">Productos</span><strong>${inventoryCount}</strong></div><div><span class="muted">Unidades</span><strong>${inventoryUnits}</strong></div></div><div class="store-actions" style="margin-top:18px;display:flex;gap:8px;flex-wrap:wrap;"><button class="outline" type="button" data-action="edit-store" data-store-id="${storeItem.id}">Editar local</button><button class="outline" type="button" data-action="local-inventory" data-store-id="${storeItem.id}">Inventario</button><button class="outline" type="button" data-action="local-transfer" data-store-id="${storeItem.id}">Trasladar</button></div></div></div>`; $('.modal-close').onclick=()=>$('#modal-root').innerHTML=''; }
function saleDetail(saleId){ const sale = (store.collection.sales || []).find(item => String(item.id) === String(saleId)) || (store.collection.ventas || []).find(item => String(item.id) === String(saleId)); if(!sale) return; const customerName = sale.customer || sale.cliente || sale.cliente_nombre || 'Cliente'; const saleStore = (store.collection.stores || []).find(item => String(item.id) === String(sale.storeId || sale.local_id || sale.local)) || {name: sale.storeName || sale.local || 'Sin local'}; const rows = (sale.items && sale.items.length) ? sale.items : ((store.collection.movimiento_productos || []).filter(item => String(item.movimiento_id) === String(sale.movimiento_id ?? sale.id)).map(item => ({ productId:String(item.codigo || item.descripcion || ''), quantity:Number(item.cantidad || 0), price:Number(item.precio_unitario || 0), subtotal:Number(item.precio_total || 0), name:String(item.descripcion || item.producto || item.codigo || 'Producto') }))); const total = Number(sale.total || rows.reduce((sum,item)=>sum + Number(item.subtotal || (Number(item.quantity||0) * Number(item.price||0))), 0)); $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal"><button type="button" class="modal-close">×</button><p class="eyebrow">DETALLE DE VENTA</p><h2>${sale.id}</h2><div class="detail-grid"><div><span>Cliente</span><strong>${customerName}</strong></div><div><span>Local</span><strong>${saleStore.name}</strong></div><div><span>Fecha</span><strong>${sale.date || sale.fecha || '-'}</strong></div><div><span>Vendedor</span><strong>${sale.vendedor || sale.user || sale.empleado || 'No informado'}</strong></div><div><span>Metodo de pago</span><strong>${sale.paymentMethod || sale.metodo_pago || 'Sin dato'}</strong></div><div><span>Total</span><strong>${money(total)}</strong></div></div><h3>Productos</h3>${table(['Producto','Cantidad','Valor unitario','Subtotal'], rows.map(item => `<tr><td>${item.name || item.productId || 'Producto'}</td><td>${item.quantity || 0}</td><td>${money(Number(item.price || 0))}</td><td>${money(Number(item.subtotal || ((Number(item.quantity||0) * Number(item.price||0)) || 0)))}</td></tr>`))}<p class="muted">Estado: ${sale.status || 'Completada'}</p></section></div>`; $('.modal-close').onclick=()=>$('#modal-root').innerHTML=''; }
function resolveSellerName(sale){ const value=sale.seller || sale.vendedor || sale.empleado || sale.usuario || sale.usuario_nombre || sale.userName || sale.user || sale.createdBy || sale.created_by || sale.userId || sale.usuario_id || ''; const user=(store.collection.users||[]).find(item=>String(item.id)===String(value)||String(item.username)===String(value)); return canonicalSellerName(user?.name || user?.username || value); }
function decorateSaleSeller(saleId){ const sale=(store.collection.sales||[]).find(item=>String(item.id)===String(saleId)) || (store.collection.ventas||[]).find(item=>String(item.id)===String(saleId)); const field=[...document.querySelectorAll('#modal-root .detail-grid > div')].find(item=>item.querySelector('span')?.textContent.trim()==='Vendedor'); if(sale&&field)field.querySelector('strong').textContent=resolveSellerName(sale); }
function openSellerRanking(){ const ranking=new Map(); const currentMonth = new Date().toISOString().slice(0,7); normalizeSales(store.collection.sales || store.collection.ventas || []).filter(sale => String(sale.date || sale.fecha || sale.createdAt || '').slice(0,7) === currentMonth).forEach(sale=>{const name=resolveSellerName(sale);const entry=ranking.get(name)||{name,count:0,total:0};entry.count+=1;entry.total+=Number(sale.total||0);ranking.set(name,entry);});const rows=[...ranking.values()].sort((left,right)=>right.total-left.total||right.count-left.count);const best=rows[0];const monthLabel = new Date().toLocaleDateString('es-CO',{month:'long',year:'numeric'});$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal seller-ranking-modal"><button type="button" class="modal-close">×</button><p class="eyebrow">ANALITICA COMERCIAL</p><h2>Ranking mensual de vendedores</h2><p class="muted">Ventas registradas en ${monthLabel}.</p>${best?`<div class="seller-ranking-highlight"><span>MEJOR VENDEDOR</span><strong>${best.name}</strong><b>${money(best.total)}</b></div>`:'<p class="muted">No hay ventas registradas este mes.</p>'}${rows.length?table(['Posicion','Vendedor','Ventas','Total vendido'],rows.map((item,index)=>`<tr><td><strong>${index+1}</strong></td><td>${item.name}</td><td>${item.count}</td><td><strong>${money(item.total)}</strong></td></tr>`)):''}</section></div>`;$('.modal-close').onclick=()=>$('#modal-root').innerHTML=''; }
window.addEventListener('open-seller-ranking',openSellerRanking);
function attachSaleItemForm(saleId){
	if(!canPerform('Ventas','edit'))return;
	const sale=(store.collection.sales||[]).find(item=>String(item.id)===String(saleId)) || (store.collection.ventas||[]).find(item=>String(item.id)===String(saleId));
	if(!sale)return;
	const storeId=sale.storeId || sale.local_id || sale.local;
	const options=(store.collection.products||[]).map(product=>{const stock=(store.collection.inventoryByStore||[]).find(item=>String(item.productId)===String(product.id)&&String(item.storeId)===String(storeId))?.quantity ?? 0;return `<option value="${product.id}" ${stock<=0?'disabled':''}>${product.name} · ${product.code||product.id} · Stock: ${stock}</option>`;}).join('');
	const form=document.createElement('form');
	form.id='add-sale-item-form';
	form.className='sale-item-form';
	form.innerHTML=`<details><summary>Agregar producto faltante</summary><div class="sale-item-fields"><label class="input-label">Producto<select class="field" name="productId" required>${options}</select></label><label class="input-label">Cantidad<input class="field" name="quantity" type="number" min="1" step="1" value="1" required></label><label class="input-label">Valor unitario<input class="field" name="unitPrice" type="number" min="0" step="1" required></label><button class="primary wide">Agregar y descontar inventario</button></div></details>`;
	$('#modal-root .modal')?.append(form);
	form.addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));const button=form.querySelector('button');button.disabled=true;try{await persistCatalogRecord('/api/catalog/sale-item',{saleId,productId:values.productId,quantity:Number(values.quantity),unitPrice:Number(values.unitPrice),tenantId:activeTenantId()});const normalized=await hydrateState();if(normalized){store.state=normalized;await hydrateCatalog(store.state);}$('#modal-root').innerHTML='';saleDetail(saleId);attachSaleItemForm(saleId);showToast('Producto agregado y descontado del inventario.');}catch(error){showToast(error.message,'error');button.disabled=false;}});
}
function openSaleEditModal(saleId){const sale=store.collection.sales.find(item=>String(item.id)===String(saleId));if(!sale)return;const customers=store.collection.customers.map(item=>`<option value="${item.id}" ${String(item.id)===String(sale.customerId)?'selected':''}>${item.name}</option>`).join('');const saleDate=String(sale.date||sale.fecha||'').slice(0,10);$('#modal-root').innerHTML=`<div class="modal-backdrop"><form class="modal" id="sale-edit-modal"><button type="button" class="modal-close">×</button><p class="eyebrow">ADMINISTRACION</p><h2>Editar venta ${sale.id}</h2><label class="input-label">Fecha de la venta<input class="field" name="date" type="date" value="${saleDate}" required></label><label class="input-label">Cliente<select class="field" name="customerId">${customers}</select></label><label class="input-label">Metodo de pago<select class="field" name="paymentMethod"><option ${sale.paymentMethod==='Efectivo'?'selected':''}>Efectivo</option><option ${sale.paymentMethod==='Transferencia'?'selected':''}>Transferencia</option><option ${sale.paymentMethod==='Tarjeta'?'selected':''}>Tarjeta</option><option ${String(sale.paymentMethod).toLowerCase().includes('credito')?'selected':''}>Crédito interno FAMIMUEBLES</option><option ${sale.paymentMethod==='Apartado'?'selected':''}>Apartado</option></select></label><button class="primary wide">Guardar cambios</button></form></div>`;$('.modal-close').onclick=()=>$('#modal-root').innerHTML='';$('#sale-edit-modal').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button.primary');button.disabled=true;try{const values=Object.fromEntries(new FormData(event.target));const response=await persistCatalogRecord('/api/catalog/sale', {...sale,...values},'PUT');const normalized=await hydrateState();if(normalized){store.state=normalized;await hydrateCatalog(store.state);}const savedSale=store.collection.sales.find(item=>String(item.id)===String(saleId));if(!savedSale||String(savedSale.date||savedSale.fecha||'').slice(0,10)!==values.date)throw new Error('La fecha no quedo confirmada en PostgreSQL. Intenta nuevamente.');$('#modal-root').innerHTML='';render();showToast(response?.date?'Venta y fecha actualizadas correctamente.':'Venta actualizada correctamente.');}catch(error){showToast(error.message,'error');button.disabled=false;}};}
async function deleteSale(saleId){if(!window.confirm('¿Eliminar esta venta? El inventario sera revertido y quedara registro de auditoria.'))return;try{await persistCatalogRecord(`/api/catalog/sale/${encodeURIComponent(saleId)}`,{},'DELETE');const normalized=await hydrateState();if(normalized){store.state=normalized;await hydrateCatalog(store.state);}$('#modal-root').innerHTML='';render();showToast('Venta eliminada e inventario revertido.');}catch(error){showToast(error.message,'error');}}
function deleteLocalTransfer(transferId){if(!window.confirm('¿Eliminar este traslado?'))return;const transfer=store.collection.transfers.find(item=>String(item.id)===String(transferId));if(!transfer)return;try{runTransaction(store.collection,()=>{if(transfer.status==='EN_TRANSITO')transfer.items.forEach(item=>increaseStock(store.collection,item.productId,transfer.originStoreId,item.quantity,transfer.id,'ANULACION_TRASLADO'));if(transfer.status==='RECIBIDO'){transfer.items.forEach(item=>{decreaseStock(store.collection,item.productId,transfer.destinationStoreId,item.quantity,transfer.id,'ANULACION_TRASLADO');increaseStock(store.collection,item.productId,transfer.originStoreId,item.quantity,transfer.id,'ANULACION_TRASLADO');});}store.collection.transfers=store.collection.transfers.filter(item=>item.id!==transfer.id);store.collection.auditLog.push({id:generateId('AUD',store.collection.auditLog),date:new Date().toISOString(),userId:'USR-00001',action:'Eliminar traslado',transferId:transfer.id});});store.save();render();showToast('Traslado eliminado e inventario revertido.');}catch(error){showToast(error.message,'error');}}
async function deleteLocalPurchase(purchaseId){
	if(!window.confirm('¿Eliminar esta compra?'))return;
	const purchase=(store.collection.purchases||[]).find(item=>String(item.id)===String(purchaseId)) || (store.collection.entries||[]).find(item=>String(item.id)===String(purchaseId));
	if(!purchase)return;
	try{
		const remoteEntryId=purchase.remoteEntryId || purchase.movementId || purchase.movimiento_id || purchase.id;
		const isSharedEntry=Boolean(purchase.sharedEntry || purchase.remoteEntryId || purchase.movementId || !String(purchase.id).startsWith('COM-'));
		if(isSharedEntry) await persistCatalogRecord(`/api/shared-entry/${encodeURIComponent(remoteEntryId)}`,{},'DELETE');
		else await persistCatalogRecord(`/api/domain/purchases/${encodeURIComponent(purchase.id)}`,{},'DELETE');
		if(isSharedEntry) await hydrateCatalog(store.state);
		if(String(purchase.status||'').toUpperCase()==='RECIBIDA' && Array.isArray(purchase.items) && !isSharedEntry){
			purchase.items.forEach(item=>decreaseStock(store.collection,item.productId,purchase.storeId,item.quantity,purchase.id,'ANULACION_COMPRA'));
		}
		store.collection.purchases = (store.collection.purchases || []).filter(item=>String(item.id)!==String(purchaseId));
		store.collection.entries = (store.collection.entries || []).filter(item=>String(item.id)!==String(purchaseId));
		store.collection.accountsPayable=(store.collection.accountsPayable||[]).filter(item=>String(item.purchaseId)!==String(purchaseId));
		store.save();
		render();
		showToast('Compra eliminada.');
	}catch(error){showToast(error.message,'error');}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const storeId=button.dataset.storeId;if(button.dataset.action==='toggle-store')toggleStore(storeId);if(button.dataset.action==='delete-store')deleteStore(storeId);});
