function openCreditEditModal(id){const item=store.collection.credits.find(entry=>String(entry.id)===String(id));if(!item)return;const fields=[['total','Valor total',item.total,'number'],['initial','Cuota inicial',item.initial||item.downPayment||0,'number'],['installmentsCount','Numero de cuotas',item.installmentsCount||1,'number'],['status','Estado',item.status||'Al dia']];$('#modal-root').innerHTML=`<div class="modal-backdrop"><form class="modal" id="credit-edit-form"><button type="button" class="modal-close">×</button><p class="eyebrow">ADMINISTRACION</p><h2>Editar credito</h2>${fields.map(field=>`<label class="input-label">${field[1]}<input class="field" name="${field[0]}" type="${field[3]||'text'}" value="${field[2]??''}" required></label>`).join('')}<button class="primary wide">Guardar cambios</button></form></div>`;$('.modal-close').onclick=()=>$('#modal-root').innerHTML='';$('#credit-edit-form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));const total=Number(values.total),initial=Number(values.initial),installmentsCount=Number(values.installmentsCount);if(!Number.isFinite(total)||total<0||!Number.isFinite(initial)||initial<0||initial>total||!Number.isInteger(installmentsCount)||installmentsCount<1)return showToast('Los valores del credito no son validos.','error');const updated={...item,...values,total,originalAmount:total,initial,downPayment:initial,financedAmount:total-initial,installmentsCount,installmentAmount:(total-initial)/installmentsCount};try{await persistDomainRecord('credits',updated);const index=store.collection.credits.findIndex(entry=>String(entry.id)===String(id));store.collection.credits[index]=updated;store.save();$('#modal-root').innerHTML='';render();showToast('Credito actualizado correctamente.');}catch(error){showToast(error.message,'error');}};}
