function pickRemoteNumber(row = {}, keys = []) {
	for (const key of keys) {
		if (!row || !Object.prototype.hasOwnProperty.call(row, key)) continue;
		const value = row[key];
		if (value === null || value === undefined || value === '') continue;
		const parsed = Number(value);
		if (Number.isFinite(parsed)) return parsed;
	}
	return 0;
}

function parseRemoteRowData(item = {}) {
	const raw = item && item.data_json;
	if (!raw) return item;
	try {
		const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
		if (parsed && typeof parsed === 'object') return { ...item, ...parsed };
	} catch (error) {
		// Ignorar si el JSON anidado no es válido.
	}
	return item;
}

function ensureRemoteHistoryCollections() {
	if (!store.collection.remoteMode) return;
	const storeByCode = new Map((store.collection.stores || []).map(item => [String(item.code || item.id || '').toUpperCase(), item.id]));
	const storeByName = new Map((store.collection.stores || []).map(item => [String(item.name || '').toUpperCase(), item.id]));
	const customerCandidates = [...(Array.isArray(store.collection.customers) ? store.collection.customers : []), ...(Array.isArray(store.collection.clientes) ? store.collection.clientes : [])];
	const customerByName = new Map(customerCandidates.map(item => [String(item.name || item.nombre || '').trim().toLowerCase(), String(item.id ?? '')]));
	const customerByDocument = new Map(customerCandidates.map(item => [String(item.document || item.documento || '').trim(), String(item.id ?? '')]));
	const resolveCustomerId = row => {
		const direct = [row.customerId, row.cliente_id, row.id_cliente, row.customer_id, row.clienteId, row.id_cliente_telegram];
		for (const candidate of direct) {
			if (candidate !== undefined && candidate !== null && candidate !== '') return String(candidate);
		}
		const names = [row.customer, row.cliente, row.cliente_nombre, row.nombre_cliente, row.name, row.nombre];
		for (const name of names) {
			if (!name) continue;
			const key = String(name).trim().toLowerCase();
			if (customerByName.has(key)) return customerByName.get(key);
		}
		const docs = [row.document, row.documento, row.numero_documento];
		for (const doc of docs) {
			if (!doc) continue;
			const key = String(doc).trim();
			if (customerByDocument.has(key)) return customerByDocument.get(key);
		}
		return '';
	};
	const getStoreId = value => {
		if (!value && value !== 0) return '';
		const text = String(value).trim();
		if (!text) return '';
		return storeByCode.get(text.toUpperCase()) || storeByName.get(text.toUpperCase()) || text;
	};
	const movementProducts = Array.isArray(store.collection.movementProducts) ? store.collection.movementProducts : (Array.isArray(store.collection.movimiento_productos) ? store.collection.movimiento_productos : []);
	const detailsByMovement = new Map();
	movementProducts.forEach(detail => {
		const key = String(detail.movimiento_id ?? detail.movement_id ?? detail.movimiento ?? '');
		if (!key) return;
		const bucket = detailsByMovement.get(key) || [];
		bucket.push(detail);
		detailsByMovement.set(key, bucket);
	});
	const joinSales = [...(Array.isArray(store.collection.sales) ? store.collection.sales : []), ...(Array.isArray(store.collection.movimientos) ? store.collection.movimientos.filter(item => String(item.tipo || '').toUpperCase() === 'VENTA') : [])];
	store.collection.sales = joinSales.map(item => {
		const row = parseRemoteRowData(item);
		const detailRows = detailsByMovement.get(String(row.id ?? row.movimiento_id ?? row.movement_id ?? '')) || [];
		const items = Array.isArray(row.items) && row.items.length ? row.items : detailRows.map(detail => ({
			productId: String(detail.codigo || detail.producto || detail.descripcion || ''),
			name: String(detail.descripcion || detail.producto || detail.codigo || 'Producto'),
			quantity: Number(detail.cantidad || 0),
			price: Number(detail.precio_unitario || 0),
			subtotal: Number(detail.precio_total || 0),
		}));
		return {
			...row,
			id: String(row.id ?? row.factura ?? row.numero_factura ?? row.invoiceId ?? ''),
			customerId: resolveCustomerId(row),
			customer: String(row.customer ?? row.cliente ?? row.cliente_nombre ?? row.customer_name ?? row.nombre_cliente ?? 'Cliente'),
			storeId: getStoreId(row.storeId ?? row.local_id ?? row.local ?? row.local_origen ?? row.local_destino),
			date: String(row.date ?? row.fecha ?? row.fecha_venta ?? row.createdAt ?? ''),
			paymentMethod: String(row.paymentMethod ?? row.metodo_pago ?? row.forma_pago ?? 'Sin dato'),
			total: pickRemoteNumber(row, ['total_venta', 'valor_total', 'monto', 'total', 'valor', 'amount']),
			status: String(row.status ?? row.estado ?? 'Completada'),
			items,
			vendedor: String(row.vendedor ?? row.seller ?? row.empleado ?? row.usuario ?? row.vendor ?? row.createdBy ?? row.created_by ?? 'No informado'),
			seller: String(row.vendedor ?? row.seller ?? row.empleado ?? row.usuario ?? row.vendor ?? row.createdBy ?? row.created_by ?? ''),
			movimiento_id: row.movimiento_id ?? row.id ?? '',
		};
	});
	store.collection.ventas = store.collection.sales;
	store.collection.credits = (Array.isArray(store.collection.credits) ? store.collection.credits : []).map(item => {
		const row = parseRemoteRowData(item);
		const sale = Array.isArray(store.collection.sales) ? store.collection.sales.find(candidate => String(candidate.id) === String(row.venta_id ?? row.saleId ?? '')) : null;
		return {
			...row,
			id: String(row.id ?? 'CR-01'),
			customerId: resolveCustomerId(row) || (sale ? sale.customerId : ''),
			customer: String(row.customer ?? row.cliente ?? sale?.customer ?? 'Sin cliente'),
			date: String(row.date ?? row.fecha ?? row.creado_en ?? ''),
			total: pickRemoteNumber(row, ['total', 'valor_total', 'monto', 'amount']),
			initial: pickRemoteNumber(row, ['initial', 'abono_inicial', 'cuota_inicial', 'downPayment']),
			paid: pickRemoteNumber(row, ['paid', 'pagado', 'abonos', 'valor_pagado']),
			saldo_pendiente: pickRemoteNumber(row, ['saldo_pendiente', 'balance', 'pendingBalance']),
			status: String(row.status ?? row.estado ?? 'PENDIENTE'),
		};
	});
	store.collection.apartados = (Array.isArray(store.collection.apartados) ? store.collection.apartados : []).map(item => {
		const row = parseRemoteRowData(item);
		return {
			...row,
			id: String(row.id ?? row.numero_recibo ?? 'APT-01'),
			customerId: resolveCustomerId(row),
			customer: String(row.customer ?? row.cliente ?? row.cliente_nombre ?? 'Sin cliente'),
			total: pickRemoteNumber(row, ['total', 'valor_total', 'monto', 'amount']),
			initial: pickRemoteNumber(row, ['initial', 'abono_inicial', 'cuota_inicial', 'downPayment']),
			paid: pickRemoteNumber(row, ['paid', 'valor_pagado', 'pagado']),
			saldo_pendiente: pickRemoteNumber(row, ['saldo_pendiente', 'balance', 'pendingBalance']),
			date: String(row.date ?? row.fecha ?? row.creado_en ?? ''),
			status: String(row.status ?? row.estado ?? 'Activo'),
			storeId: getStoreId(row.storeId ?? row.local_id ?? row.local),
		};
	});
	store.collection.expenses = (Array.isArray(store.collection.gastos) ? store.collection.gastos : []).map(item => {
		const row = parseRemoteRowData(item);
		return {
			...row,
			id: String(row.id ?? 'GASTO-01'),
			date: String(row.date ?? row.fecha ?? ''),
			storeId: getStoreId(row.storeId ?? row.local_id ?? row.local),
			category: String(row.category ?? row.categoria ?? 'General'),
			description: String(row.description ?? row.detalle ?? row.descripcion ?? 'Sin descripción'),
			amount: pickRemoteNumber(row, ['amount', 'valor', 'total', 'monto']),
			paymentMethod: String(row.paymentMethod ?? row.metodo_pago ?? 'N/A'),
			createdBy: String(row.createdBy ?? row.empleado ?? row.usuario ?? 'Sistema')
		};
	});
	store.collection.gastos = store.collection.expenses;
	store.collection.fuelRecords = (Array.isArray(store.collection.gasolina) ? store.collection.gasolina : []).map(item => {
		const row = parseRemoteRowData(item);
		return {
			...row,
			id: String(row.id ?? 'FUE-01'),
			date: String(row.date ?? row.fecha ?? ''),
			storeId: getStoreId(row.storeId ?? row.local_id ?? row.local),
			vehicle: String(row.vehicle ?? row.carro ?? row.vehiculo ?? 'N/A'),
			driver: String(row.driver ?? row.conductor ?? row.empleado ?? 'N/A'),
			quantity: pickRemoteNumber(row, ['quantity', 'cantidad', 'litros', 'galones']),
			amount: pickRemoteNumber(row, ['amount', 'valor', 'total', 'monto']),
			unit: String(row.unit ?? (Number(row.quantity ?? row.cantidad ?? row.galones ?? 0) > 0 ? 'galones' : 'litros')),
			mileage: Number(row.mileage ?? row.kilometraje ?? row.km_actual ?? 0),
			station: String(row.station ?? row.estacion ?? row.lugar ?? 'N/A')
		};
	});
	store.collection.gasolina = store.collection.fuelRecords;
	store.collection.movimientos = Array.isArray(store.collection.movements) ? store.collection.movements : (Array.isArray(store.collection.movimientos) ? store.collection.movimientos : []);
	store.collection.purchases = (Array.isArray(store.collection.movimientos) ? store.collection.movimientos.filter(item => String(item.tipo || '').toUpperCase() === 'ENTRADA') : []).map(item => {
		const row = parseRemoteRowData(item);
		const details = detailsByMovement.get(String(row.id)) || [];
		const total = Number(row.total ?? row.valor ?? row.monto ?? details.reduce((sum, detail) => sum + Number(detail.precio_total ?? detail.precio_unitario ?? 0) * Number(detail.cantidad ?? 1), 0) ?? 0);
		return {
			...row,
			id: String(row.id ?? 'ENTR-01'),
			storeId: getStoreId(row.local_id ?? row.local),
			createdAt: String(row.fecha ?? row.creado_en ?? ''),
			supplierName: String(row.proveedor ?? row.empleado ?? 'Proveedor'),
			total,
			status: String(row.estado ?? 'RECIBIDA')
		};
	});
}

function normalizeRemoteTransfers() {
	if (!store.collection.remoteMode) return;
  store.collection.transfers=(store.collection.transfers || []).map(item => {
    const status=String(item.estado || item.status || 'COMPLETADO').toUpperCase();
    const items=Array.isArray(item.items) && item.items.length ? item.items : [{ productId:String(item.codigo || ''), quantity:Number(item.cantidad || 0) }];
    return { ...item, id:String(item.id), originStoreId:String(item.originStoreId || item.local_origen_id || item.local_origen || ''), destinationStoreId:String(item.destinationStoreId || item.local_destino_id || item.local_destino || ''), createdAt:item.createdAt || item.fecha || item.creado_en || '', createdBy:String(item.createdBy || item.usuario_id || item.empleado || ''), status:status === 'COMPLETADO' ? 'RECIBIDO' : status, items:items.map(detail => ({ ...detail, productId:String(detail.productId || detail.codigo || ''), quantity:Number(detail.quantity ?? detail.cantidad ?? 0) })) };
  });
	render();
}